import { useState } from "react"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
} from "@/hoogin/ui/navigation/sidebar"
import { ChevronRightIcon } from "lucide-react"
import { Link, useMatches } from "@tanstack/react-router"
import type {
  SidebarNavItem,
  SidebarNavSubItem,
} from "@/hoogin/ui/navigation/sidebar.types"

function isSubItemActive(sub: SidebarNavSubItem, fullPath: string): boolean {
  if (sub.url === fullPath) return true
  return sub.items?.some((child) => isSubItemActive(child, fullPath)) ?? false
}

function NavSubItem({
  sub,
  fullPath,
}: {
  sub: SidebarNavSubItem
  fullPath: string
}) {
  const active = isSubItemActive(sub, fullPath)
  const [open, setOpen] = useState(active)
  if (!sub.items?.length) {
    return (
      <SidebarMenuSubItem>
        <SidebarMenuSubButton
          isActive={active}
          render={<Link to={sub.url} aria-label={sub.title} />}
        >
          <span>{sub.title}</span>
        </SidebarMenuSubButton>
      </SidebarMenuSubItem>
    )
  }

  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      render={<SidebarMenuSubItem />}
    >
      <SidebarMenuSubButton
        isActive={active}
        className="pr-6"
        render={<Link to={sub.url} aria-label={sub.title} />}
      >
        <span>{sub.title}</span>
      </SidebarMenuSubButton>
      <CollapsibleTrigger
        render={
          <SidebarMenuAction className="aria-expanded:rotate-90" />
        }
      >
        <ChevronRightIcon />
        <span className="sr-only">Toggle</span>
      </CollapsibleTrigger>
      <CollapsibleContent>
        <SidebarMenuSub>
          {sub.items.map((child) => (
            <NavSubItem key={child.title} sub={child} fullPath={fullPath} />
          ))}
        </SidebarMenuSub>
      </CollapsibleContent>
    </Collapsible>
  )
}

function NavMenuItem({
  item,
  active,
  fullPath,
}: {
  item: SidebarNavItem
  active: boolean
  fullPath: string
}) {
  const [open, setOpen] = useState(active)

  return (
    <Collapsible open={open} onOpenChange={setOpen} render={<SidebarMenuItem />}>
      <SidebarMenuButton
        tooltip={item.title}
        render={<Link to={item.url} aria-label={item.title} />}
      >
        <item.icon />
        <span>{item.title}</span>
      </SidebarMenuButton>
      {item.items?.length ? (
        <>
          <CollapsibleTrigger
            render={
              <SidebarMenuAction className="aria-expanded:rotate-90" />
            }
          >
            <ChevronRightIcon />
            <span className="sr-only">Toggle</span>
          </CollapsibleTrigger>
          <CollapsibleContent>
            <SidebarMenuSub>
              {item.items.map((sub) => (
                <NavSubItem
                  key={sub.title}
                  sub={sub}
                  fullPath={fullPath}
                />
              ))}
            </SidebarMenuSub>
          </CollapsibleContent>
        </>
      ) : null}
    </Collapsible>
  )
}

export function NavMain({
  items,
  label = "Platform",
}: {
  items: SidebarNavItem[]
  label?: string
}) {
  const matches = useMatches()
  const fullPath = matches[matches.length - 1]?.fullPath ?? ""
  if (items.length === 0) {
    return null
  }

  const isItemActive = (item: SidebarNavItem) => {
    if (item.isActive) return true
    if (item.url === fullPath) return true
    return item.items?.some((sub) => isSubItemActive(sub, fullPath)) ?? false
  }

  return (
    <SidebarGroup>
      <SidebarGroupLabel>{label}</SidebarGroupLabel>
      <SidebarMenu>
        {items.map((item) => {
          const active = isItemActive(item)
          return (
            <NavMenuItem
              key={item.title}
              item={item}
              active={active}
              fullPath={fullPath}
            />
          )
        })}
      </SidebarMenu>
    </SidebarGroup>
  )
}

import * as React from "react"

import {
  SidebarGroup,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from "@/hoogin/ui/navigation/sidebar"
import type { SidebarSecondaryItem } from "@/hoogin/ui/navigation/sidebar.types"

export function NavSecondary({
  items,
  ...props
}: {
  items: SidebarSecondaryItem[]
} & React.ComponentPropsWithoutRef<typeof SidebarGroup>) {
  return (
    <SidebarGroup {...props}>
      <SidebarGroupContent>
        <SidebarMenu>
          {items.map((item) => (
            <SidebarMenuItem key={item.title}>
              <SidebarMenuButton
                size="sm"
                render={<a href={item.url} aria-label={item.title} />}
              >
                <item.icon />
                <span>{item.title}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  )
}

import { type LucideIcon } from "lucide-react"
import { type ReactNode } from "react"

export type SidebarBrand = {
  name: string
  description?: string
  logo?: ReactNode
}

export type SidebarUser = {
  name: string
  email: string
  avatar: string
}

export type SidebarNavSubItem = {
  title: string
  url: string
  items?: SidebarNavSubItem[]
}

export type SidebarNavItem = {
  title: string
  url: string
  icon: LucideIcon
  isActive?: boolean
  items?: SidebarNavSubItem[]
}

export type SidebarSecondaryItem = {
  title: string
  url: string
  icon: LucideIcon
}

export type SidebarProject = {
  name: string
  url: string
  icon: LucideIcon
}

export type SidebarMore = {
  label: string
  url: string
}

export type SidebarUserMenuItem = {
  label: string
  url: string
  icon?: LucideIcon
}

export type SidebarUserMenuGroup = {
  items: SidebarUserMenuItem[]
}

export type SidebarUserMenu = SidebarUserMenuGroup[]
